pub fn fuse(ranked_lists: &[(&[String], f64)], k: u32) -> Vec<(String, f64)> {
    let mut scores: HashMap<String, f64> = HashMap::new();

    for (ids, weight) in ranked_lists {
        for (rank, id) in ids.iter().enumerate() {
            let rank_1based = (rank + 1) as f64;
            let contribution = weight / (k as f64 + rank_1based);
            *scores.entry(id.clone()).or_default() += contribution;
        }
    }

    let mut results: Vec<(String, f64)> = scores.into_iter().collect();
    // Total order: score desc, then id asc. HashMap iteration order is
    // arbitrary, so exact-score ties must not leak map order into the
    // ranked list — downstream RRF positions feed positional scoring.
    results.sort_by(|a, b| {
        b.1.partial_cmp(&a.1)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.0.cmp(&b.0))
    });
    results
}

