fn extract_rust_module(node: &Node, source: &[u8], file_path: &str) -> Option<CodeEntity> {
    let name_node = node.child_by_field_name("name")?;
    let name = node_text(&name_node, source)?;
    let content = node_text(node, source)?;

    Some(CodeEntity {
        entity_type: "module",
        title: name.clone(),
        content,
        properties: json!({
            "file_path": file_path,
            "language": "rust",
            "module_path": name,
        }),
    })
}

fn extract_rust_type(
    node: &Node,
    source: &[u8],
    file_path: &str,
    kind: &str,
) -> Option<CodeEntity> {
    let name_node = node.child_by_field_name("name")?;
    let name = node_text(&name_node, source)?;
    let line_start = node.start_position().row + 1;
    let line_end = node.end_position().row + 1;
    let content = node_text(node, source)?;

    Some(CodeEntity {
        entity_type: "class",
        title: name.clone(),
        content,
        properties: json!({
            "file_path": file_path,
            "line_start": line_start,
            "line_end": line_end,
            "language": "rust",
            "qualified_name": name,
            "kind": kind,
        }),
    })
}

